import { createHash } from 'node:crypto'
import { readFile, stat } from 'node:fs/promises'
import { join } from 'node:path'
import { versionAtLeast } from './vault-extension-domain.js'

/**
 * NA-0194 — publishes the operator's VaultNAccess release directory (`npm run package:extension`). Nothing is
 * served unless the extension is enabled and the release matches this deployment: schema, allowed extension id,
 * version not below the minimum, and each served file's size and SHA-256 equal to release.json (checked on every download).
 * The update manifest is generated by the server from that release.
 */
export interface ExtensionPackageConfig { enabled: boolean; directory: string | undefined; extensionIds: readonly string[]; minVersion: string }
export interface ExtensionRelease { version: string; extensionId: string; zip: { file: string; sha256: string; size: number }; crx: { file: string; sha256: string; size: number } }
const MAX_BYTES = 20 * 1024 * 1024
const sha256 = (buffer: Buffer): string => createHash('sha256').update(buffer).digest('hex')
const hex64 = /^[a-f0-9]{64}$/

function parseRelease(text: string): ExtensionRelease | null {
  let value: unknown
  try { value = JSON.parse(text) } catch { return null }
  if (!value || typeof value !== 'object') return null
  const r = value as Record<string, unknown>
  const file = (x: unknown, ext: 'zip' | 'crx'): { file: string; sha256: string; size: number } | null => {
    if (!x || typeof x !== 'object') return null
    const f = x as Record<string, unknown>
    return typeof f.file === 'string' && f.file === `vaultnaccess-${String(r.version)}.${ext}` && typeof f.sha256 === 'string' && hex64.test(f.sha256)
      && typeof f.size === 'number' && Number.isSafeInteger(f.size) && f.size > 0 && f.size <= MAX_BYTES ? { file: f.file, sha256: f.sha256, size: f.size } : null
  }
  if (r.schemaVersion !== 1 || typeof r.version !== 'string' || !/^\d{1,4}\.\d{1,4}\.\d{1,4}$/.test(r.version)
    || typeof r.extensionId !== 'string' || !/^[a-p]{32}$/.test(r.extensionId)) return null
  const zip = file(r.zip, 'zip'), crx = file(r.crx, 'crx')
  return zip && crx ? { version: r.version, extensionId: r.extensionId, zip, crx } : null
}

const xml = (value: string): string => value.replace(/[<>&'"]/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', "'": '&apos;', '"': '&quot;' })[c] ?? c)
/** gupdate manifest built by the server from the verified release (never the operator's file). */
export function updateManifestFor(release: ExtensionRelease, codebase: string): string {
  return `<?xml version='1.0' encoding='UTF-8'?>\n<gupdate xmlns='http://www.google.com/update2/response' protocol='2.0'>\n  <app appid='${xml(release.extensionId)}'>\n`
    + `    <updatecheck codebase='${xml(codebase)}' version='${xml(release.version)}' />\n  </app>\n</gupdate>\n`
}

export class ExtensionPackage {
  constructor(private readonly config: ExtensionPackageConfig, private readonly read: (path: string) => Promise<Buffer> = path => readFile(path),
    private readonly size: (path: string) => Promise<number> = async path => (await stat(path)).size) {}

  /** The validated release (configuration only), or null when nothing may be published. */
  async release(): Promise<ExtensionRelease | null> {
    if (!this.config.enabled || !this.config.directory) return null
    let release: ExtensionRelease | null
    try {
      const path = join(this.config.directory, 'release.json')
      if (await this.size(path) > 65_536) return null
      release = parseRelease((await this.read(path)).toString('utf8'))
    } catch { return null }
    if (!release || !this.config.extensionIds.includes(release.extensionId) || !versionAtLeast(release.version, this.config.minVersion)) return null
    return release
  }
  /** A release file, read only when its size matches release.json and returned only when its SHA-256 matches too. */
  async file(kind: 'zip' | 'crx'): Promise<{ body: Buffer; contentType: string; release: ExtensionRelease } | null> {
    const release = await this.release()
    if (!release || !this.config.directory) return null
    const entry = kind === 'zip' ? release.zip : release.crx, path = join(this.config.directory, entry.file)
    try {
      if (await this.size(path) !== entry.size) return null
      const body = await this.read(path)
      if (body.length !== entry.size || sha256(body) !== entry.sha256) return null
      return { body, contentType: kind === 'zip' ? 'application/zip' : 'application/x-chrome-extension', release }
    } catch { return null }
  }
  /** Release whose files are both present and intact (what the portal card advertises). */
  async verified(): Promise<ExtensionRelease | null> {
    const zip = await this.file('zip'), crx = await this.file('crx')
    return zip && crx ? zip.release : null
  }
}
